extern "C" void run(RenderInput *c, float *image, int *ids, int threads) {
    memset(image, 0, size_t(c->width) * c->height * 3 * 4);
    ao_scanlines(0, c->height, c->width, c->height, c->nsubsamples, threads, image);
}
